+const getSigningKey = (): string => {
+  const key = process.env.SESSION_SIGNING_KEY;
+  if (!key) throw new Error("SESSION_SIGNING_KEY not configured");
+  return key;
+};
+
+const sign = (data: string): string => {
+  return createHmac("sha256", getSigningKey()).update(data).digest("hex");
+};
+
+const verify = (data: string, signature: string): boolean => {
+  const expected = sign(data);
+  return expected === signature;
+};
+
+export const encodeSessionToken = (
+  id: string,
+  userId: string,
+  issuedAt: number,
+): string => {
+  const data = `${id}:${userId}:${issuedAt}`;
+  const signature = sign(data);
+  return `${data}:${signature}`;
+};
+
+export const verifySessionToken = (token: string): { id: string; userId: string; issuedAt: number } | null => {
+  const parts = token.split(":");
+  if (parts.length !== 4) return null;
+
+  const [id, userId, issuedAtStr, signature] = parts;
+  const data = `${id}:${userId}:${issuedAtStr}`;
+
+  if (!verify(data, signature)) return null;
+
+  const issuedAt = parseInt(issuedAtStr, 10);
+  if (isNaN(issuedAt)) return null;
+
+  return { id, userId, issuedAt };
+};
